/**
 * @fileoverview Test the settings config
 * @author Sencha
 */
'use strict';

// ------------------------------------------------------------------------------
// Requirements
// ------------------------------------------------------------------------------

const RuleTester = require('eslint').RuleTester;
const extjs = require('../../lib/utils/extjs');
const rule = {
    create: function (context) {
        return {
            Program (node) {
                extjs.init(context);
                const userExtjsSettings = context.settings.extjs || {};

                if (typeof userExtjsSettings.version !== 'undefined') {
                    if (!extjs.isValidDoxiVersion(userExtjsSettings.version)) {
                        context.report({
                            node,
                            message: 'Invalid doxi version {{version}} specified for the {{toolkit}} toolkit.',
                            data: {
                                version: userExtjsSettings.version,
                                toolkit: extjs.extjsSettings.toolkit
                            }
                        });
                    }
                }
                if (typeof userExtjsSettings.fromVersion !== 'undefined') {
                    if (!extjs.isValidDoxiVersion(userExtjsSettings.fromVersion)) {
                        context.report({
                            node,
                            message: 'Invalid doxi fromVersion {{version}} specified for the {{toolkit}} toolkit.',
                            data: {
                                version: userExtjsSettings.fromVersion,
                                toolkit: extjs.extjsSettings.toolkit
                            }
                        });
                    }
                }
                if (typeof userExtjsSettings.toVersion !== 'undefined') {
                    if (!extjs.isValidDoxiVersion(userExtjsSettings.toVersion)) {
                        context.report({
                            node,
                            message: 'Invalid doxi toVersion {{version}} specified for the {{toolkit}} toolkit.',
                            data: {
                                version: userExtjsSettings.toVersion,
                                toolkit: extjs.extjsSettings.toolkit
                            }
                        });
                    }
                }
            }
        };
    }
}; 

